    /**
     * Tests getting all Appointments.
     *
     * @return    Collection
     */
    public List<Appointment> testGetAll() throws Throwable {
    LOGGER.info( "AppointmentTest:testGetAll() - Retrieving Collection of Appointments:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Appointment : " );
    List<Appointment> collection  = null;

    try {
        // call the static get method on the AppointmentService
        collection = service.getAllAppointment();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Appointment currEntity  = null;
            Iterator<Appointment> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAppointmentId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

